import {test,expect,type Page} from '@playwright/test'
type Preview=Window&{coachAlertFixture:{enabled:boolean;registered:boolean;available:boolean;failSave:boolean;failRead:boolean;hold:boolean;resolveFail:boolean;blocked:boolean;autoOpen:boolean;revision:number;reads:number;writes:boolean[];opens:string[];release:()=>void;resume:()=>void;tap:(recipient?:string,href?:string)=>void;mount:()=>void};switchNavigationOwner:()=>void}
async function mount(page:Page,width=390,registered=true){await page.routeWebSocket('**/*',ws=>ws.close());await page.setViewportSize({width,height:844});await page.goto('http://127.0.0.1:4283/?large=1');await expect(page.locator('#app')).toHaveAttribute('data-state','ready');await page.evaluate(value=>{const f=(window as unknown as Preview).coachAlertFixture;f.registered=value;f.mount()},registered);await expect(page.getByRole('button',{name:'Turn on Coach alerts',exact:true})).toBeVisible();return page.locator('[data-coach-alert-preview]')}
for(const width of [320,390])test('Coach alerts require a separate explicit choice at '+width+'px',async({page})=>{const host=await mount(page,width);await expect(host).toContainText('Coach alerts are off.');await expect(host.getByRole('button',{name:'Turn off team alerts',exact:true})).toBeEnabled();expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.writes)).toEqual([]);await host.getByRole('button',{name:'Turn on Coach alerts',exact:true}).click();await expect(host.getByRole('button',{name:'Turn off Coach alerts',exact:true})).toBeEnabled();await host.getByRole('button',{name:'Turn off Coach alerts',exact:true}).click();await expect(host).toContainText('Coach alerts are off.');expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.writes)).toEqual([true,false]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true)})
test('Coach alerts need registration here without changing the saved account choice',async({page})=>{const host=await mount(page,320,false);await expect(host.getByRole('button',{name:'Turn on Coach alerts',exact:true})).toBeDisabled();await expect(host).toContainText('Enable chat notifications on this iPhone');expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.writes)).toEqual([])})
test('an interrupted preference save requires a read before another change',async({page})=>{const host=await mount(page);await page.evaluate(()=>{(window as unknown as Preview).coachAlertFixture.failSave=true});await host.getByRole('button',{name:'Turn on Coach alerts',exact:true}).click();await expect(host).toContainText('Your choice wasn’t confirmed.');await page.evaluate(()=>{(window as unknown as Preview).coachAlertFixture.failSave=false});await host.getByRole('button',{name:'Check Coach alerts',exact:true}).click();await expect(host.getByRole('button',{name:'Turn off Coach alerts',exact:true})).toBeEnabled();expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.writes)).toEqual([true])})
test('an owned alert resolves the exact current connection and rejects foreign payloads',async({page})=>{await mount(page);await page.evaluate(()=>{const f=(window as unknown as Preview).coachAlertFixture;f.tap('foreign');f.tap(undefined,'/messages?thread=aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa&owner=other')});await expect(page.getByRole('complementary',{name:'Coach message alert'})).toBeHidden();await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.tap());await page.getByRole('button',{name:'Open conversation',exact:true}).click();await expect(page.locator('[data-coach-alert-opened="student-one"]')).toBeVisible();expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.opens)).toEqual(['student-one'])})
test('an alert preserves an open form and an unavailable connection never opens another conversation',async({page})=>{await mount(page);await page.evaluate(()=>{const f=(window as unknown as Preview).coachAlertFixture;f.blocked=true;f.tap()});await page.getByRole('button',{name:'Open conversation',exact:true}).click();await expect(page.getByRole('complementary',{name:'Coach message alert'})).toContainText('Close your current form');expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.opens)).toEqual([]);await page.evaluate(()=>{const f=(window as unknown as Preview).coachAlertFixture;f.blocked=false;f.resolveFail=true});await page.getByRole('button',{name:'Open conversation',exact:true}).click();await expect(page.getByRole('complementary',{name:'Coach message alert'})).toContainText('couldn’t open');expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.opens)).toEqual([])})
test('a pending Coach alert resumes once a safe page finishes loading',async({page})=>{await mount(page);await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.tap());await expect(page.getByRole('complementary',{name:'Coach message alert'})).toBeVisible();expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.opens)).toEqual([]);await page.evaluate(()=>{const f=(window as unknown as Preview).coachAlertFixture;f.autoOpen=true;f.resume()});await expect(page.locator('[data-coach-alert-opened="student-one"]')).toBeVisible()})
test('a late old-account alert response cannot open private coaching data',async({page})=>{await mount(page);await page.evaluate(()=>{const f=(window as unknown as Preview).coachAlertFixture;f.hold=true;f.tap()});await page.getByRole('button',{name:'Open conversation',exact:true}).click();await expect(page.getByRole('complementary',{name:'Coach message alert'})).toContainText('Checking conversation');await page.evaluate(()=>{const w=window as unknown as Preview;w.switchNavigationOwner();w.coachAlertFixture.release()});await expect(page.locator('#app')).toHaveAttribute('data-state','ready');expect(await page.evaluate(()=>(window as unknown as Preview).coachAlertFixture.opens)).toEqual([])})
test('the app opens the verified Coach conversation from a cold-start native alert',async({page})=>{await page.routeWebSocket('**/*',ws=>ws.close());await page.setViewportSize({width:320,height:844});await page.goto('http://127.0.0.1:4283/?large=1&coachAlerts=1&coldCoach=1');await expect(page.getByRole('dialog',{name:'Coach messages',exact:true})).toContainText('Bring your return notes');await expect(page.getByRole('dialog',{name:'Coach messages',exact:true}).locator('[data-connection]')).toHaveValue('99999999-9999-4999-8999-999999999991');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true)})
test('multiple session callbacks retain a cold Coach conversation',async({page})=>{await page.routeWebSocket('**/*',ws=>ws.close());await page.goto('http://127.0.0.1:4283/?coachAlerts=1&coldCoach=1&duplicateAuth=1');const dialog=page.getByRole('dialog',{name:'Coach messages',exact:true});await expect(dialog).toContainText('Bring your return notes');await page.evaluate(async()=>{(window as unknown as {refreshNavigationSession:()=>void}).refreshNavigationSession();await new Promise(resolve=>setTimeout(resolve,50))});await expect(dialog).toContainText('Bring your return notes');await expect(dialog.locator('[data-connection]')).toHaveValue('99999999-9999-4999-8999-999999999991')})
test('the actual Chats settings save the separate account choice and an alert preserves a draft form',async({page})=>{await page.routeWebSocket('**/*',ws=>ws.close());await page.goto('http://127.0.0.1:4283/?large=1&coachAlerts=1');await page.locator('.app-navigation [data-screen="teams"]').click();await page.getByRole('button',{name:'Turn on Coach alerts',exact:true}).click();await expect(page.getByRole('button',{name:'Turn off Coach alerts',exact:true})).toBeEnabled();await page.locator('.native-account-entry').click();const account=page.getByRole('dialog',{name:'Account settings'});await expect(account).toBeVisible();await page.evaluate(()=>{(window as unknown as {nativeCoachAlertFixture:{tap:()=>void}}).nativeCoachAlertFixture.tap()});await expect(account).toBeVisible();await account.getByRole('button',{name:'Close account settings',exact:true}).click();await page.getByRole('button',{name:'Open conversation',exact:true}).click();await expect(page.getByRole('dialog',{name:'Coach messages',exact:true})).toContainText('Bring your return notes')})
